app.MapDelete("/teachers/{id:int}", async (int id, CollegeDbContext db)=>{ var value=await db.Teachers.FindAsync(id); if(value is null) return Results.NotFound(); db.Remove(value); try {await db.SaveChangesAsync();} catch(DbUpdateException) {return Results.Conflict("Record is referenced by other records");} return Results.NoContent(); });
