app.MapGet("/subjects/{id:int}", async (int id, CollegeDbContext db)=> await db.Subjects.FindAsync(id) is {} value ? Results.Ok(value) : Results.NotFound());
app.MapPost("/subjects/add", async (Subject value, CollegeDbContext db)=>{ if (string.IsNullOrWhiteSpace(value.SubjectName) || !await db.Teachers.AnyAsync(x=>x.TeacherId==value.TeacherId)) return Results.BadRequest("Invalid data"); value.SubjectId=0; db.Subjects.Add(value); await db.SaveChangesAsync(); return Results.Created($"/subjects/{value.SubjectId}",value.SubjectId); });
app.MapPut("/subjects/{id:int}", async (int id, Subject value, CollegeDbContext db)=>{ var existing=await db.Subjects.FindAsync(id); if(existing is null) return Results.NotFound(); if (string.IsNullOrWhiteSpace(value.SubjectName) || !await db.Teachers.AnyAsync(x=>x.TeacherId==value.TeacherId)) return Results.BadRequest("Invalid data"); value.SubjectId=id; db.Entry(existing).CurrentValues.SetValues(value); await db.SaveChangesAsync(); return Results.NoContent(); });
app.MapDelete("/subjects/{id:int}", async (int id, CollegeDbContext db)=>{ var value=await db.Subjects.FindAsync(id); if(value is null) return Results.NotFound(); db.Remove(value); try {await db.SaveChangesAsync();} catch(DbUpdateException) {return Results.Conflict("Record is referenced by other records");} return Results.NoContent(); });
app.MapGet("/grades/all", async (CollegeDbContext db)=>Results.Ok(await db.Grades.AsNoTracking().ToListAsync()));
app.MapGet("/grades/{id:int}", async (int id, CollegeDbContext db)=> await db.Grades.FindAsync(id) is {} value ? Results.Ok(value) : Results.NotFound());
app.MapPost("/grades/add", async (Grade value, CollegeDbContext db)=>{ if (value.Value<1 || value.Value>5 || !await db.Students.AnyAsync(x=>x.StudentId==value.StudentId) || !await db.Subjects.AnyAsync(x=>x.SubjectId==value.SubjectId)) return Results.BadRequest("Invalid data"); value.GradeId=0; db.Grades.Add(value); await db.SaveChangesAsync(); return Results.Created($"/grades/{value.GradeId}",value.GradeId); });
app.MapPut("/grades/{id:int}", async (int id, Grade value, CollegeDbContext db)=>{ var existing=await db.Grades.FindAsync(id); if(existing is null) return Results.NotFound(); if (value.Value<1 || value.Value>5 || !await db.Students.AnyAsync(x=>x.StudentId==value.StudentId) || !await db.Subjects.AnyAsync(x=>x.SubjectId==value.SubjectId)) return Results.BadRequest("Invalid data"); value.GradeId=id; db.Entry(existing).CurrentValues.SetValues(value); await db.SaveChangesAsync(); return Results.NoContent(); });
app.MapDelete("/grades/{id:int}", async (int id, CollegeDbContext db)=>{ var value=await db.Grades.FindAsync(id); if(value is null) return Results.NotFound(); db.Remove(value); try {await db.SaveChangesAsync();} catch(DbUpdateException) {return Results.Conflict("Record is referenced by other records");} return Results.NoContent(); });
app.Run();